  }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;


#pragma scop
{
  const int TS = 32;
  for (j = 0; j < n; j++) {
    DATA_TYPE diag = A[j][j];
    #pragma omp parallel default(none) shared(A, n, j, diag)
    {
      int kk, k, kend;
      #pragma omp for schedule(static, TS)
      for (i = j; i < n; i++) {
        if (i == j) {
          for (kk = 0; kk < j; kk += TS) {
            kend = (kk + TS < j) ? kk + TS : j;
            for (k = kk; k < kend; k++)
              diag -= A[j][k] * A[j][k];
          }
        } else {
