            kend = (kk + TS < j) ? kk + TS : j;
            for (k = kk; k < kend; k++)
              A[i][j] -= A[i][k] * A[j][k];
          }
        }
      }
      #pragma omp single
      {
        diag = SQRT_FUN(diag);
        A[j][j] = diag;
      }
      #pragma omp for schedule(static, TS)
      for (i = j + 1; i < n; i++) {
        A[i][j] /= diag;
      }
    }
  }
}
#pragma endscop

}


int main(int argc, char** argv)
{
